import java.util.*;
class Product {
    int productId;
    char lowFats;
    char recyclable;
    Product(int id, char l, char r) { productId = id; lowFats = l; recyclable = r; }
}
class Solution {
    public List<Integer> findProducts(List<Product> products) {
        List<Integer> ans = new ArrayList<>();
        for (Product p : products) {
            if (p.lowFats == 'Y' && p.recyclable == 'Y') {
                ans.add(p.productId);
            }
        }
        return ans;
    }
}

