struct Product {
    int product_id;
    char low_fats;
    char recyclable;
};
class Solution {
public:
    vector<int> findProducts(vector<Product>& products) {
        vector<Product> filtered;
        filtered.reserve(products.size());
        copy_if(products.begin(), products.end(), back_inserter(filtered), [](const Product& p) {
            return p.low_fats == 'Y' && p.recyclable == 'Y';
        });
        vector<int> ans;
        ans.reserve(filtered.size());
        for (auto &p : filtered) ans.push_back(p.product_id);
        return ans;
    }
};

