import java.util.*;
import java.util.stream.*;
class Product {
    int productId;
    char lowFats;
    char recyclable;
    Product(int id, char l, char r) { productId = id; lowFats = l; recyclable = r; }
}
class Solution {
    public List<Integer> findProducts(List<Product> products) {
        return products.stream().filter(p -> p.lowFats == 'Y' && p.recyclable == 'Y').map(p -> p.productId).collect(Collectors.toList());
    }
}
